PRAGMA foreign_keys = ON;
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL COLLATE NOCASE UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('admin','staff','customer')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE customers (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, phone TEXT NOT NULL DEFAULT '', company TEXT NOT NULL DEFAULT '', billing_address TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '');
CREATE TABLE product_variants (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, price_delta REAL NOT NULL DEFAULT 0);
CREATE TABLE plans (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, price REAL NOT NULL, billing_period TEXT NOT NULL, minimum_quantity INTEGER NOT NULL DEFAULT 1, available_from TEXT NOT NULL, available_to TEXT NOT NULL, features TEXT NOT NULL DEFAULT '[]', allows_renewal INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'Open');
CREATE TABLE subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), plan_id INTEGER NOT NULL REFERENCES plans(id), number TEXT NOT NULL UNIQUE, start_date TEXT NOT NULL, expiry_date TEXT NOT NULL, payment_terms TEXT NOT NULL DEFAULT 'Due on receipt', status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE subscription_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, subscription_id INTEGER NOT NULL REFERENCES subscriptions(id) ON DELETE CASCADE, product TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, tax_rate REAL NOT NULL DEFAULT 0, discount_rate REAL NOT NULL DEFAULT 0);
CREATE TABLE invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), subscription_id INTEGER REFERENCES subscriptions(id), number TEXT NOT NULL UNIQUE, date TEXT NOT NULL, due_date TEXT NOT NULL, status TEXT NOT NULL, note TEXT NOT NULL DEFAULT '');
CREATE TABLE invoice_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_id INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, product TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price REAL NOT NULL, tax_rate REAL NOT NULL DEFAULT 0, discount_rate REAL NOT NULL DEFAULT 0);
CREATE TABLE payments (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), invoice_id INTEGER NOT NULL REFERENCES invoices(id), date TEXT NOT NULL, method TEXT NOT NULL, amount REAL NOT NULL, note TEXT NOT NULL DEFAULT '');
CREATE TABLE discounts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, percentage REAL NOT NULL);
CREATE TABLE taxes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, rate REAL NOT NULL);
CREATE TABLE renewal_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), subscription_id INTEGER NOT NULL REFERENCES subscriptions(id), note TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'Pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE support_tickets (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), subject TEXT NOT NULL, category TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE password_reset_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, used_at TEXT);
CREATE INDEX idx_subscriptions_customer ON subscriptions(customer_id, status);
CREATE INDEX idx_invoices_customer_date ON invoices(customer_id, date DESC);
CREATE INDEX idx_payments_customer_date ON payments(customer_id, date DESC);
CREATE INDEX idx_reset_token_hash ON password_reset_tokens(token_hash);